import React from "react";
import styled, { createGlobalStyle } from "styled-components";
import { useTranslation } from "react-i18next";
import Zoom from "react-medium-image-zoom";
import "react-medium-image-zoom/dist/styles.css";

const GlobalStyle = createGlobalStyle`
  /* Ghi đè lại kích thước zoom */
  .react-medium-image-zoom__zoomed {
    transform: scale(5) !important; /* Zoom lên 5 lần */
    transform-origin: center !important;
  }
`;

const Container = styled.div`
  padding: 20px;
  text-align: center;
`;

const Title = styled.h2`
  font-size: 24px;
  margin-bottom: 20px;
`;

const ImageWrapper = styled.div`
  display: inline-block;
`;

const StyledImage = styled.img`
  width: 600px;
  height: 400px;
  object-fit: cover;
  border-radius: 10px;
  border: 1px solid #ccc;
  cursor: zoom-in;
`;

const DatasetStatistic = () => {
  const { t } = useTranslation();

  return (
    <Container>
      <GlobalStyle />
      <Title>{t("datasetStatistic.title")}</Title>
      <ImageWrapper>
        <Zoom>
          <StyledImage src="/Statistic1.jpg" alt="Statistic" />
        </Zoom>
      </ImageWrapper>
    </Container>
  );
};

export default DatasetStatistic;
